      'ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣੇ ਕਾਰਡ ਲੰਮੇ ਅੰਤਰਾਲ ਬਾਅਦ ਵਾਪਸ ਆਉਂਦੇ ਹਨ ਅਤੇ ਖੁੰਝੇ ਕਾਰਡ ਜਲਦੀ ਵਾਪਸ ਆਉਂਦੇ ਹਨ (ਅੰਤਰਾਲ ਦੁਹਰਾਈ)। ਹਰ ਜਵਾਬ ਨੂੰ ਦੁਬਾਰਾ, ਔਖਾ, ਵਧੀਆ ਜਾਂ ਆਸਾਨ ਰੇਟ ਕਰੋ। ਰੋਜ਼ਾਨਾ ਟੀਚਾ ਸੈੱਟ ਕਰੋ ਅਤੇ ਅੱਜ ਕਾਰਡ ’ਤੇ ਆਪਣੀ ਲੜੀ ਬਣਾਈ ਰੱਖੋ। ਬਾਕੀ ਦਿਨ ਅਤੇ ਹਰ ਰੋਜ਼ ਕਿੰਨੇ ਨਵੇਂ ਕਾਰਡ ਸਿੱਖਣੇ ਹਨ ਇਹ ਦੇਖਣ ਲਈ ਡੈੱਕ ਵਿੱਚ ਇਮਤਿਹਾਨ ਦੀ ਮਿਤੀ ਸੈੱਟ ਕਰੋ। ਕਾਰਡਾਂ ਨੂੰ ਘਸੀਟ ਕੇ ਥਾਂ ’ਤੇ ਲਿਆਉਣ ਲਈ \"ਮੇਰਾ ਕ੍ਰਮ\" ਅਨੁਸਾਰ ਕ੍ਰਮਬੱਧ ਕਰੋ, ਸੁਣਨ ਲਈ ਕਿਸੇ ਵੀ ਪਾਸੇ ਦੇ ਸਪੀਕਰ ’ਤੇ ਟੈਪ ਕਰੋ, ਅਤੇ ਗਤੀ ਤੇ ਦੁਹਰਾਓ ਬੋਲੀ ਮੀਨੂ ਵਿੱਚ ਸੈੱਟ ਕਰੋ।';

  @override
