  @override
  String get faqImportA =>
      'ਹਾਂ। ਡੈੱਕ ਵਿੱਚ ਆਯਾਤ ਚੁਣੋ, ਫਿਰ ਫਾਈਲ ਚੁਣੋ: Anki (.apkg), Excel (.xlsx) ਜਾਂ CSV, ਅਤੇ ਕਾਲਮ ਮਿਲਾਓ। ਕੰਪਿਊਟਰ ’ਤੇ ਕਾਰਡ ਲਿਖਣ ਲਈ “ਸਪ੍ਰੈਡਸ਼ੀਟ ਟੈਂਪਲੇਟ” ਵਰਤੋ। Anki ਫਾਈਲਾਂ ਵਿਚਲੀਆਂ ਤਸਵੀਰਾਂ ਅਤੇ ਧੁਨੀਆਂ ਆਯਾਤ ਨਹੀਂ ਹੁੰਦੀਆਂ।';

  @override
