  @override
  String get faqNotesA =>
      'ਜਾਂਚ ਸੂਚੀਆਂ ਅਤੇ ਫਾਰਮੈਟਿੰਗ ਨਾਲ ਖੁੱਲ੍ਹ ਕੇ ਲਿਖੋ, ਮਹੱਤਵਪੂਰਨ ਨੋਟ ਪਿੰਨ ਕਰੋ ਜਾਂ ਮਨਪਸੰਦ ਬਣਾਓ, ਟੈਗ ਸ਼ਾਮਲ ਕਰੋ ਅਤੇ ਨੋਟਾਂ ਨੂੰ ਕੰਮਾਂ ਨਾਲ ਲਿੰਕ ਕਰੋ। ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਬਟਨ ਨਾਲ ਬੋਲ ਕੇ ਲਿਖਵਾ ਸਕਦੇ ਹੋ। ਨਵਾਂ ਨੋਟ ਟੈਂਪਲੇਟ ਤੋਂ ਸ਼ੁਰੂ ਹੋ ਸਕਦਾ ਹੈ (ਲੈਕਚਰ, ਕਿਤਾਬ ਦਾ ਸਾਰ, ਡਾਇਰੀ, ਹਫ਼ਤਾਵਾਰੀ ਯੋਜਨਾ), ਅਤੇ ਤਸਵੀਰ ਬਟਨ ਫ਼ੋਟੋਆਂ ਜੋੜਦਾ ਹੈ।';

