  @override
  String get faqGuardA =>
      'ਫੋਕਸ → ਟਾਈਮਰ ਸੈਟਿੰਗਾਂ → ਧਿਆਨ ਭਟਕਣ ਤੋਂ ਸੁਰੱਖਿਆ ਖੋਲ੍ਹੋ। ਐਪਾਂ ਚੁਣੋ, ਫਿਰ ਨਰਮ (5 ਸਕਿੰਟ ਦਾ ਸਾਹ ਅਤੇ \"ਕੀ ਤੁਹਾਨੂੰ ਹੁਣ ਇਸ ਐਪ ਦੀ ਲੋੜ ਹੈ?\" ਸਵਾਲ) ਜਾਂ ਸਖ਼ਤ (ਉਹ ਬੰਦ ਰਹਿੰਦੀਆਂ ਹਨ) ਚੁਣੋ। ਇਹ ਫੋਕਸ ਸੈਸ਼ਨਾਂ ਦੌਰਾਨ ਅਤੇ ਟਾਈਮ ਗਾਰਡ ਨਾਲ ਤੁਹਾਡੇ ਨਿਰਧਾਰਤ ਦਿਨਾਂ ਅਤੇ ਘੰਟਿਆਂ ਵਿੱਚ ਕੰਮ ਕਰਦੀ ਹੈ। \"ਸਿਰਫ਼ ਚੁਣੀਆਂ ਐਪਾਂ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ\" ਬਾਕੀ ਸਭ ਕੁਝ ਰੋਕਦਾ ਹੈ; ਕਾਲਾਂ, ਸੈਟਿੰਗਾਂ ਅਤੇ ਕੀਬੋਰਡ ਹਮੇਸ਼ਾ ਕੰਮ ਕਰਦੇ ਹਨ। Android ਤੁਹਾਨੂੰ ਇੱਕ ਵਾਰ ਪਹੁੰਚਯੋਗਤਾ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸੁਰੱਖਿਆ ਚਾਲੂ ਕਰਨ ਲਈ ਕਹਿੰਦਾ ਹੈ। ਇਹ ਸਿਰਫ਼ ਦੇਖਦੀ ਹੈ ਕਿ ਕਿਹੜੀ ਐਪ ਖੁੱਲ੍ਹੀ ਹੈ ਅਤੇ ਕੁਝ ਨਹੀਂ ਭੇਜਦੀ।';

